const err = $input.item.json;
const error = err.error || {};
const payload = err.data && typeof err.data === 'object' ? err.data : (err.data || {});
function sanitize(v){
  if (v === null || v === undefined) return '';
  if (typeof v === 'object') return JSON.stringify(v).replace(/(secret|token|password|api[_ -]?key|authorization|bearer)(["']?\s*[:=]\s*)([^,}"'\s]+)/gi, '$1$2[REDACTED]');
  return String(v);
}
return [{ json: {
  error_id: 'err_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8),
  created_at: new Date().toISOString(),
  workflow: err.workflowId || 'unknown_workflow',
  node: (error.node && error.node.name) || error.node || '',
  business_id: sanitize(payload.business_id),
  lead_id: sanitize(payload.lead_id),
  error_message: String(error.message || err.errorMessage || 'unknown error').slice(0, 2000),
  execution_id: err.executionId || '',
  payload: sanitize(payload).slice(0, 4000),
  resolved: false
} }];

